/** PERSONAJES P07-HF1: native Node PNG inspection and environment diagnostics.
 * No assertions removed. Diagnostic compares compressed PNG SHA256 AND
 * all decoded RGBA pixels; NEVER equates unequal pixel payloads to success.
 * PNGs generated by our project use 8-bit RGBA, single IHDR, filter 0.
 */
import {createHash} from 'node:crypto';
import {inflateSync} from 'node:zlib';
const sha256=x=>createHash('sha256').update(x).digest('hex');
const BE=(buf,n)=>buf.readUInt32BE(n);
const CRC_TABLE=Uint32Array.from({length:256},(_,i)=>{
 let c=i;for(let j=0;j<8;j++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0;
});
function crc32(data){
 let v=0xffffffff;
 for(const b of data)v=CRC_TABLE[(v^b)&255]^(v>>>8);
 return (v^0xffffffff)>>>0;
}
export function readP07Png(buffer){
 const png=Buffer.from(buffer),signature=Buffer.from([137,80,78,71,13,10,26,10]);
 if(!png.subarray(0,8).equals(signature))throw Error('P07 PNG invalid signature');
 const chunks=[];let p=8;
 while(p<png.length){
  if(p+12>png.length)throw Error('P07 truncated PNG chunk');
  const len=BE(png,p),end=p+12+len;
  if(end>png.length)throw Error('P07 chunk outside file');
  const kind=png.toString('ascii',p+4,p+8),payload=png.subarray(p+8,p+8+len),
   storedCRC=BE(png,p+8+len),calculatedCRC=crc32(png.subarray(p+4,p+8+len));
  if(storedCRC!==calculatedCRC)throw Error('P07 PNG CRC mismatch in '+kind);
  chunks.push({kind,len,payload});p=end;
  if(kind==='IEND'&&p!==png.length)throw Error('Unexpected PNG bytes after IEND');
 }
 const ihdr=chunks.find(x=>x.kind==='IHDR')?.payload;
 if(!ihdr||ihdr.length!==13)throw Error('Missing P07 IHDR');
 const width=BE(ihdr,0),height=BE(ihdr,4),bitDepth=ihdr[8],colorType=ihdr[9],compression=ihdr[10],filter=ihdr[11],interlace=ihdr[12];
 if(width!==1408||height!==832||bitDepth!==8||colorType!==6||compression!==0||filter!==0||interlace!==0)
  throw Error('P07 unexpected PNG format '+JSON.stringify({width,height,bitDepth,colorType,compression,filter,interlace}));
 const zlib=Buffer.concat(chunks.filter(x=>x.kind==='IDAT').map(x=>x.payload)),raw=inflateSync(zlib),stride=width*4;
 if(raw.length!==(stride+1)*height)throw Error('P07 invalid decompressed byte count '+raw.length);
 const rgba=Buffer.allocUnsafe(width*height*4);let nonzero=0,partial=0,border=0,fringe=0,frames=new Array(32).fill(0);
 for(let y=0;y<height;y++){
  const inrow=y*(stride+1),outrow=y*stride;
  if(raw[inrow]!==0)throw Error('P07 unexpected row filter '+raw[inrow]+' at y='+y);
  raw.copy(rgba,outrow,inrow+1,inrow+1+stride);
  for(let x=0;x<width;x++){
   const i=outrow+x*4,a=rgba[i+3];
   if(a){nonzero++;frames[(Math.floor(y/208)*8+Math.floor(x/176))]++;if(a<255)partial++;
    if(x%176===0||x%176===175||y%208===0||y%208===207)border++;
   }else if(rgba[i]||rgba[i+1]||rgba[i+2])fringe++;
  }
 }
 const gammaChunk=chunks.find(x=>x.kind==='gAMA');
 return {
  summary:{pngBytes:png.length,pngSha256:sha256(png),rgbaBytes:rgba.length,rgbaSha256:sha256(rgba),
   compressedIdatBytes:zlib.length,width,height,bitDepth,colorType,alpha:true,
   alphaVisiblePixels:nonzero,alphaPartialPixels:partial,alphaBorderContacts:border,
   transparentNonzeroRgbPixels:fringe,emptyFrames:frames.filter(x=>x===0).length,
   gamma:gammaChunk?BE(gammaChunk.payload,0)/100000:null,
   sRGB:chunks.some(x=>x.kind==='sRGB'),
   chunkNames:chunks.map(x=>x.kind),crcValid:true},
  rgba,frames,png
 };
}
function firstDiff(a,b){
 const len=Math.min(a.length,b.length);
 for(let i=0;i<len;i++)if(a[i]!==b[i])return i;
 return a.length===b.length?-1:len;
}
export function reportP07Mismatch(storedBytes,regenBytes,assetId){
 const a=readP07Png(storedBytes),b=readP07Png(regenBytes);
 const firstPNG=firstDiff(a.png,b.png),firstRGBA=firstDiff(a.rgba,b.rgba),affected=[];
 if(firstRGBA!==-1){
  for(let frame=0;frame<32;frame++){
   const cx=(frame%8)*176,cy=Math.floor(frame/8)*208;
   let mismatchCount=0;
   for(let yy=cy;yy<cy+208;yy++)for(let xx=cx;xx<cx+176;xx++){
    const offset=(yy*1408+xx)*4;
    if(a.rgba[offset]!==b.rgba[offset]||a.rgba[offset+1]!==b.rgba[offset+1]||
       a.rgba[offset+2]!==b.rgba[offset+2]||a.rgba[offset+3]!==b.rgba[offset+3])
      mismatchCount++;
   }
   if(mismatchCount)affected.push({frame,differentPixels:mismatchCount});
  }
 }
 const x=Math.floor(Math.max(firstRGBA,0)/4)%1408,y=Math.floor(Math.max(firstRGBA,0)/4/1408);
 return {
  actorId:assetId,classification:firstRGBA<0&&firstPNG>=0?'ENCODING_OR_METADATA_ONLY':
   firstRGBA>=0?'RASTER_RGBA_DIFFERENT':'BYTE_IDENTICAL',
  stored:a.summary,regenerated:b.summary,
  firstDifferentPngByte:firstPNG,
  firstDifferentRgbaByte:firstRGBA,
  firstPixel:firstRGBA<0?null:{
   x,y,frame:Math.floor(y/208)*8+Math.floor(x/176),
   channel:['R','G','B','A'][firstRGBA%4],
   storedValue:a.rgba[firstRGBA]??null,
   regeneratedValue:b.rgba[firstRGBA]??null
  },
  affectedFrames:affected
 };
}
